wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(36894960969316771912)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'HTML Text Email Using PL/SQL'
,p_static_id=>'html-text-email-using-pl-sql'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    -- Configuration for Subject Line',
'    l_subject   VARCHAR2(255) := ''Styled HTML Email Using PL/SQL'';',
'    ',
'    -- Containers for plain text fallback and rich HTML markup',
'    l_body_text CLOB;',
'    l_body_html CLOB;',
'BEGIN',
'    ----------------------------------------------------------------------------',
'    -- 1. Define Plain Text Fallback Body',
'    ----------------------------------------------------------------------------',
'    -- Sent alongside HTML to support legacy mail clients or text-only viewers',
'    l_body_text := ''Hello, This is a styled HTML demo email sent using PL/SQL APEX_MAIL.SEND.'';',
'',
'    ----------------------------------------------------------------------------',
'    -- 2. Define Styled HTML Email Body',
'    ----------------------------------------------------------------------------',
'    -- Contains inline CSS and HTML structures for rich-text rendering',
'    l_body_html := ''<!DOCTYPE html>',
'    <html>',
'    <head>',
'        <style>',
'            body { font-family: Arial, sans-serif; color: #333; line-height: 1.6; }',
'            .card { max-width: 500px; margin: 10px auto; padding: 20px; border: 1px solid #28a745; border-radius: 8px; background-color: #f8f9fa; }',
'            .header { color: #28a745; margin-top: 0; }',
'            .badge { background-color: #28a745; color: white; padding: 4px 8px; border-radius: 4px; font-size: 12px; }',
'        </style>',
'    </head>',
'    <body>',
'        <div class="card">',
'            <h3 class="header">APEX HTML Email Demo</h3>',
'            <p>Hello,</p>',
'            <p>This is a <strong>custom HTML formatted email</strong> sent directly via PL/SQL code.</p>',
'            <p>Status: <span class="badge">SUCCESS</span></p>',
'            <hr style="border: none; border-top: 1px solid #ddd; margin: 15px 0;">',
'            <p style="font-size: 12px; color: #666;">Sent from Oracle APEX Engine</p>',
'        </div>',
'    </body>',
'    </html>'';',
'',
'    ----------------------------------------------------------------------------',
'    -- 3. Enqueue Email Message',
'    ----------------------------------------------------------------------------',
'    -- APEX_MAIL.SEND stores the email with both plain text and HTML payloads',
'    apex_mail.send(',
'        p_to        => ''archi.patel@tavishinfotech.com'',  -- Recipient email address',
'        p_from      => :APP_EMAIL,                  -- Sender email address (fetches Application Item :APP_EMAIL)',
'        p_body      => l_body_text,                 -- Plain text fallback content',
'        p_body_html => l_body_html,                 -- Rich HTML formatted content',
'        p_subj      => l_subject                    -- Email subject line',
'    );',
'',
'    ----------------------------------------------------------------------------',
'    -- 4. Flush Mail Queue Immediately',
'    ----------------------------------------------------------------------------',
'    -- Forces immediate dispatch from the internal mail queue',
'    apex_mail.push_queue;',
'',
'EXCEPTION',
'    ----------------------------------------------------------------------------',
'    -- Error Handling Block',
'    ----------------------------------------------------------------------------',
'    WHEN OTHERS THEN',
'        -- Traps runtime errors and raises an inline APEX page notification',
'        apex_error.add_error(',
'            p_message          => ''HTML Email sending failed: '' || SQLERRM,',
'            p_display_location => apex_error.c_inline_in_notification',
'        );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(36894960570729771908)
,p_process_success_message=>'HTML Text Email Send Successfully Using PL/SQL !'
,p_internal_uid=>36894960969316771912
,p_created_on=>wwv_flow_imp.dz('20260910052303Z')
,p_updated_on=>wwv_flow_imp.dz('20260910052603Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
