,p_process_name=>'HTML Text Email Using Process'
,p_static_id=>'html-text-email-using-process'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'body_html', wwv_flow_string.join(wwv_flow_t_varchar2(
    '<!DOCTYPE html>',
    '    <html>',
    '    <head>',
    '        <style>',
    '            body { font-family: Arial, sans-serif; color: #333; line-height: 1.6; }',
    '            .card { max-width: 500px; margin: 10px auto; padding: 20px; border: 1px solid #28a745; border-radius: 8px; background-color: #f8f9fa; }',
    '            .header { color: #28a745; margin-top: 0; }',
    '            .badge { background-color: #28a745; color: white; padding: 4px 8px; border-radius: 4px; font-size: 12px; }',
    '        </style>',
    '    </head>',
    '    <body>',
    '        <div class="card">',
    '            <h3 class="header">APEX HTML Email Demo</h3>',
    '            <p>Hello,</p>',
    '            <p>This is a <strong>custom HTML formatted email</strong> sent directly via Send E-Mail Process.</p>',
    '            <p>Status: <span class="badge">SUCCESS</span></p>',
    '            <hr style="border: none; border-top: 1px solid #ddd; margin: 15px 0;">',
    '            <p style="font-size: 12px; color: #666;">Sent from Oracle APEX Engine</p>',
    '        </div>',
    '    </body>',
    '    </html>')),
  'body_plain_text', 'System generated email.',
  'from', '&APP_EMAIL.',
  'send_immediately', 'Y',
  'subject', 'Test Email - APEX Email Application Demo',
  'to', 'ARCHI.PATEL@TAVISHINFOTECH.COM')).to_clob
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(36894960291925771905)
,p_process_success_message=>'HTML Text Email Send Successfully !'
,p_internal_uid=>36894960729121771910
,p_created_on=>wwv_flow_imp.dz('20260910051807Z')
,p_updated_on=>wwv_flow_imp.dz('20260910051807Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(36894960861244771911)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Plain Text Email Using PL/SQL'
,p_static_id=>'plain-text-email-using-pl-sql'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    -- Email Subject line configuration',
'    l_subject VARCHAR2(255) := ''Simple Text Email Using PL/SQL'';',
'    ',
'    -- Plain text content container for email body',
'    l_body    CLOB;',
'BEGIN',
'    ----------------------------------------------------------------------------',
'    -- 1. Construct Plain Text Email Body',
'    ----------------------------------------------------------------------------',
'    -- Building email message using CHR(10) for line breaks (Newlines)',
'    l_body := ''Hello,'' || CHR(10) || CHR(10)',
'           || ''This is a simple plain text demo email sent using PL/SQL APEX_MAIL.SEND.'' || CHR(10)',
'           || ''If you are reading this, the email delivery engine is working correctly.'' || CHR(10) || CHR(10)',
'           || ''Regards,'' || CHR(10)',
'           || ''APEX Demo App'';',
'',
'    ----------------------------------------------------------------------------',
'    -- 2. Stage Email in APEX Mail Queue',
'    ----------------------------------------------------------------------------',
'    -- APEX_MAIL.SEND enqueues the message into the internal mail log table',
'    apex_mail.send(',
'        p_to   => ''archi.patel@tavishinfotech.com'',  -- Recipient email address',
'        p_from => :APP_EMAIL,                  -- Sender email address (fetches Application Item :APP_EMAIL)',
'        p_body => l_body,                      -- Plain text email body content',
'        p_subj => l_subject                    -- Email subject line',
'    );',
'',
'    ----------------------------------------------------------------------------',
'    -- 3. Force Immediate Email Delivery',
'    ----------------------------------------------------------------------------',
'    -- By default, APEX sends queued emails via a background job schedule.',
'    -- Calling push_queue forces APEX to immediately dispatch all queued emails.',
'    apex_mail.push_queue;',
'',
'EXCEPTION',
'    ----------------------------------------------------------------------------',
'    -- Error Handling Block',
'    ----------------------------------------------------------------------------',
'    WHEN OTHERS THEN',
'        -- Catches runtime errors (e.g., SMTP failure, invalid email format)',
'        -- and displays a user-friendly notification message on the APEX page UI.',
'        apex_error.add_error(',
'            p_message          => ''Email sending failed: '' || SQLERRM,',
'            p_display_location => apex_error.c_inline_in_notification',
'        );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(36894960487481771907)
,p_process_success_message=>'Plain Text Email Send Successfully Using PL/SQL !'
,p_internal_uid=>36894960861244771911
,p_created_on=>wwv_flow_imp.dz('20260910052303Z')
,p_updated_on=>wwv_flow_imp.dz('20260910052603Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(36894960619856771909)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_SEND_EMAIL'
,p_process_name=>'Plain Text Email Using Process'
,p_static_id=>'plain-text-email-using-process'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'body_plain_text', wwv_flow_string.join(wwv_flow_t_varchar2(
    'Hello,',
    '',
    'This is a test email sent from Oracle APEX Application to verify the email delivery setup.',
    '',
    'If you received this message, the email configuration and process are working correctly.',
    '',
    'Regards,',
    'APEX Demo App')),
  'from', '&APP_EMAIL.',
  'send_immediately', 'Y',
  'subject', 'Test Email - APEX Email Application Demo',
  'to', 'archi.patel@tavishinfotech.com')).to_clob
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(36894960195910771904)
