wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(36894962387744771926)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Send Email PL/SQL For With Placeholder Template'
,p_static_id=>'send-email-pl-sql-for-with-placeholder-template'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    -- Shared Components -> Email Templates me defined Template Static ID',
'    c_template_id CONSTANT VARCHAR2(100) := ''email-template-with-placeholder'';',
'    ',
'    -- JSON payload hold karne ke liye CLOB variable container',
'    l_placeholders CLOB;',
'BEGIN',
'    ----------------------------------------------------------------------------',
'    -- 1. Build JSON Payload for Template Placeholders',
'    ----------------------------------------------------------------------------',
'    -- Constructing key-value pairs using JSON_OBJECT.',
'    -- Note: JSON keys must exactly match the placeholder tags in the HTML template ',
'    -- without the surrounding hashes (e.g., ''USER_NAME'' corresponds to ''#USER_NAME#'').',
'    l_placeholders := json_object(',
'        ''PROCESS''   VALUE ''PL/SQL'',                            -- Value for #PROCESS#',
'        ''USER_NAME''    VALUE ''Archi'',                      -- Value for #APP_NAME#',
'        ''APP_NAME''      VALUE ''Send Email'',                                 -- Value for #APP_NAME#',
'        ''STATUS'' VALUE ''Success'',                   -- Value for #STATUS#',
'        ''MODULE_NAME''   VALUE ''Email Template'', -- System timestamp for #MODULE_NAME#',
'        ''TEST_DATE''   VALUE TO_CHAR(GET_IST_SYSTIMESTAMP, ''DD-MON-YYYY HH:MM AM'') -- System timestamp for #TEST_DATE#',
'    );',
'',
'    ----------------------------------------------------------------------------',
'    -- 2. Dispatch Email Using APEX Email Template',
'    ----------------------------------------------------------------------------',
'    -- APEX_MAIL.SEND API fetches the template from Shared Components and ',
'    -- merges the JSON placeholders into the template structure.',
'    apex_mail.send(',
'        p_to                 => ''archi.patel@tavishinfotech.com'',  -- Target recipient email address',
'        p_from               => :APP_EMAIL,                  -- Sender address from Application Item (:APP_EMAIL)',
'        p_template_static_id => c_template_id,              -- Target Email Template Static ID',
'        p_placeholders       => l_placeholders               -- JSON string payload containing dynamic values',
'    );',
'',
'    ----------------------------------------------------------------------------',
'    -- 3. Push Email Queue Immediately',
'    ----------------------------------------------------------------------------',
'    -- Forces immediate dispatch from the internal mail queue to the SMTP server ',
'    -- instead of waiting for the default APEX background job execution.',
'    apex_mail.push_queue;',
'',
'EXCEPTION',
'    ----------------------------------------------------------------------------',
'    -- Error Handling Block',
'    ----------------------------------------------------------------------------',
'    WHEN OTHERS THEN',
'        -- Catches runtime errors (e.g., Template ID mismatch, invalid JSON structure, SMTP failure)',
'        -- and presents a clean error message in the APEX user interface.',
'        apex_error.add_error(',
'            p_message          => ''Dynamic template email sending failed: '' || SQLERRM,',
'            p_display_location => apex_error.c_inline_in_notification',
'        );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(36894961702073771920)
,p_process_success_message=>'With Placeholder Email Template Email Send Successfully Using PL/SQL !'
,p_internal_uid=>36894962387744771926
,p_created_on=>wwv_flow_imp.dz('20260911052051Z')
,p_updated_on=>wwv_flow_imp.dz('20260911052512Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(36894962192812771924)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Send Email PL/SQL For Without Placeholder Template'
,p_static_id=>'send-email-pl-sql-for-without-placeholder-template'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    -- Shared Components -> Email Templates me defined Template Static ID',
'    c_template_id CONSTANT VARCHAR2(100) := ''email-template-without-placeholder'';',
'BEGIN',
'    ----------------------------------------------------------------------------',
'    -- 1. Send Email Using Static APEX Email Template (Without Placeholders)',
'    ----------------------------------------------------------------------------',
'    -- APEX_MAIL.SEND API triggers the template registered in Shared Components.',
'    -- Empty JSON object ''{}'' is passed since this template has no dynamic placeholders.',
'    apex_mail.send(',
'        p_to                 => ''archi.patel@tavishinfotech.com'',  -- Recipient email address',
'        p_from               => :APP_EMAIL,                  -- Sender address from Application Item (:APP_EMAIL)',
'        p_template_static_id => c_template_id,              -- Target Email Template Static ID',
'        p_placeholders       => ''{}''                         -- Empty JSON payload (No dynamic variables)',
'    );',
'',
'    ----------------------------------------------------------------------------',
'    -- 2. Force Immediate Delivery from APEX Mail Queue',
'    ----------------------------------------------------------------------------',
'    -- Pushes queued email messages immediately to SMTP server instead of waiting ',
'    -- for the default APEX background job schedule.',
'    apex_mail.push_queue;',
'',
'EXCEPTION',
'    ----------------------------------------------------------------------------',
'    -- Error Handling Section',
'    ----------------------------------------------------------------------------',
'    WHEN OTHERS THEN',
'        -- Traps runtime errors (e.g., Template ID mismatch, SMTP failure) ',
'        -- and displays an inline notification message on the APEX page UI.',
'        apex_error.add_error(',
'            p_message          => ''Demo template email sending failed: '' || SQLERRM,',
'            p_display_location => apex_error.c_inline_in_notification',
'        );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(36894961440467771917)
,p_process_success_message=>'Without Placeholder Email Template Email Send Successfully Using PL/SQL !'
,p_internal_uid=>36894962192812771924
,p_created_on=>wwv_flow_imp.dz('20260911052051Z')
,p_updated_on=>wwv_flow_imp.dz('20260911052051Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
