wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(36894964665238771949)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Generate Excel And Store In Collection'
,p_static_id=>'generate-excel-and-store-in-collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    -- Collection configuration',
'    c_collection_name CONSTANT VARCHAR2(100) := ''EXCEL_ATTACHMENT_COLL'';',
'    ',
'    -- Variables for Execution & Data Export',
'    l_context         APEX_EXEC.t_context;',
'    l_export          APEX_DATA_EXPORT.t_export;',
'    l_blob            BLOB;',
'    ',
'    -- Variables for Role & File Naming',
'    l_role_name       VARCHAR2(200);',
'    l_filename        VARCHAR2(255);',
'    l_sql_query       VARCHAR2(4000);',
'BEGIN',
'    ----------------------------------------------------------------------------',
'    -- 1. Check & Re-create APEX Collection',
'    ----------------------------------------------------------------------------',
'    -- Agar collection pehle se exist karta hai toh drop karke naya create karein',
'    IF apex_collection.collection_exists(p_collection_name => c_collection_name) THEN',
'        apex_collection.delete_collection(p_collection_name => c_collection_name);',
'    END IF;',
'',
'    -- Create new fresh collection',
'    apex_collection.create_collection(p_collection_name => c_collection_name);',
'',
'    ----------------------------------------------------------------------------',
'    -- 2. Fetch Role Name from Database',
'    ----------------------------------------------------------------------------',
'    BEGIN',
'        SELECT role_name ',
'          INTO l_role_name',
'          FROM LWF_ROLES',
'         WHERE role_id = :P6_ROLE_ID;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            l_role_name := ''User_Report'';',
'    END;',
'',
'    ----------------------------------------------------------------------------',
'    -- 3. Define SQL Query',
'    ----------------------------------------------------------------------------',
'    l_sql_query := ''SELECT',
'                        U.FIRST_NAME,',
'                        U.LAST_NAME,',
'                        U.EMAIL,',
'                        U.MOBILE_NUMBER,',
'                        R.ROLE_NAME',
'                    FROM LWF_USERS U',
'                    JOIN LWF_ROLES R ON U.ROLE_ID = R.ROLE_ID',
'                    WHERE R.ROLE_ID = :P6_ROLE_ID'';',
'',
'    ----------------------------------------------------------------------------',
'    -- 4. Open Context & Export Data to XLSX',
'    ----------------------------------------------------------------------------',
'    -- Open SQL query context',
'    l_context := apex_exec.open_query_context(',
'        p_location  => apex_exec.c_location_local_db,',
'        p_sql_query => l_sql_query',
'    );',
'',
'    -- Export context data to binary Excel XLSX format',
'    l_export := apex_data_export.export(',
'        p_context => l_context,',
'        p_format  => apex_data_export.c_format_xlsx',
'    );',
'',
'    -- Fetch the generated BLOB content',
'    l_blob := l_export.content_blob;',
'',
'    -- Close APEX_EXEC context',
'    apex_exec.close(l_context);',
'',
'    ----------------------------------------------------------------------------',
'    -- 5. Generate Dynamic Filename & Store in APEX Collection',
'    ----------------------------------------------------------------------------',
'    l_filename := ''User_List_'' || REPLACE(l_role_name, '' '', ''_'') || ''_'' || TO_CHAR(SYSDATE, ''YYYYMMDD_HH24MISS'') || ''.xlsx'';',
'',
'    apex_collection.add_member(',
'        p_collection_name => c_collection_name,',
'        p_c001            => l_role_name,                                                          -- Role Name',
'        p_c002            => l_filename,                                                           -- File Name (.xlsx)',
'        p_c003            => ''application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'',  -- XLSX MIME Type',
'        p_blob001         => l_blob                                                                -- Excel File BLOB',
'    );',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        -- Safely close query context if open',
'        BEGIN',
'            apex_exec.close(l_context);',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                NULL; -- Context already closed or not initialized',
'        END;',
'        ',
'        apex_error.add_error(',
'            p_message          => ''Excel Collection Process failed: '' || SQLERRM,',
'            p_display_location => apex_error.c_inline_in_notification',
'        );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(36894964435098771947)
,p_internal_uid=>36894964665238771949
,p_created_on=>wwv_flow_imp.dz('20260911055646Z')
,p_updated_on=>wwv_flow_imp.dz('20260911055646Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(37339633143590973901)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Send Email PL/SQL With Attachment  '
,p_static_id=>'send-email-pl-sql-with-attachment'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- DECLARE',
'--     -- 1. Configuration & Variable Declarations',
'--     l_recipient_email VARCHAR2(255) := ''ARCHI.PATEL@TAVISHINFOTECH.COM'';',
'--     l_subject         VARCHAR2(255) := ''Direct Excel Export & Email Verification Using PL/SQL'';',
'    ',
'-- h    l_context         APEX_EXEC.t_context;',
'--     l_export          APEX_DATA_EXPORT.t_export;',
'--     l_excel_blob      BLOB;',
'--     l_filename        VARCHAR2(255);',
'--     l_mime_type       VARCHAR2(255) := ''application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'';',
'    ',
'--     -- Variables for Email Execution',
'--     l_mail_id         NUMBER;',
'--     l_body_text       CLOB;',
'--     l_role_name       VARCHAR2(200);',
'--     l_sql_query       VARCHAR2(4000);',
'-- BEGIN',
'--     ----------------------------------------------------------------------------',
'--     -- STEP 1: Fetch Role Name for File Naming & Context',
'--     ----------------------------------------------------------------------------',
'--     BEGIN',
'--         SELECT role_name ',
'--           INTO l_role_name',
'--           FROM LWF_ROLES',
'--          WHERE role_id = :P6_ROLE_ID;',
'--     EXCEPTION',
'--         WHEN NO_DATA_FOUND THEN',
'--             l_role_name := ''User_Report'';',
'--     END;',
'',
'--     -- Generate Dynamic Excel File Name (e.g., User_List_ADMIN_20260810_144811.xlsx)',
'--     l_filename := ''User_List_'' || REPLACE(l_role_name, '' '', ''_'') || ''_'' || TO_CHAR(SYSDATE, ''YYYYMMDD_HH24MISS'') || ''.xlsx'';',
'',
'--     ----------------------------------------------------------------------------',
'--     -- STEP 2: Generate Native Excel (.xlsx) using APEX_EXEC & APEX_DATA_EXPORT',
'--     ----------------------------------------------------------------------------',
'--     -- Construct SQL Query using Page Item bind variable :P5_ROLE_ID',
'--     l_sql_query := ''SELECT',
'--                         U.FIRST_NAME,',
'--                         U.LAST_NAME,',
'--                         U.EMAIL,',
'--                         U.MOBILE_NUMBER,',
'--                         R.ROLE_NAME',
'--                     FROM LWF_USERS U',
'--                     JOIN LWF_ROLES R ON U.ROLE_ID = R.ROLE_ID',
'--                     WHERE R.ROLE_ID = :P6_ROLE_ID'';',
'',
'--     -- Open SQL query execution context',
'--     l_context := apex_exec.open_query_context(',
'--         p_location  => apex_exec.c_location_local_db,',
'--         p_sql_query => l_sql_query',
'--     );',
'',
'--     -- Export dataset directly to binary XLSX format',
'--     l_export := apex_data_export.export(',
'--         p_context => l_context,',
'--         p_format  => apex_data_export.c_format_xlsx',
'--     );',
'',
'--     -- Extract BLOB content from export structure',
'--     l_excel_blob := l_export.content_blob;',
'',
'--     -- Close execution context to free cursor resources',
'--     apex_exec.close(l_context);',
'',
'--     ----------------------------------------------------------------------------',
'--     -- STEP 3: Construct Plain Text Email Body',
'--     ----------------------------------------------------------------------------',
'--     l_body_text := ''*** THIS IS A DEMO / TEST EMAIL WITH DIRECT EXCEL ATTACHMENT USING PL/SQL***'' || CHR(10)',
'--                 || ''======================================================================'' || CHR(10) || CHR(10)',
'--                 || ''Hello Administrator,'' || CHR(10) || CHR(10)',
'--                 || ''Please find attached the exported User Details Report generated for Role: '' || l_role_name || ''.'' || CHR(10) || CHR(10)',
'--                 || ''Execution Details:'' || CHR(10)',
'--                 || ''----------------------------------------------------------------------'' || CHR(10)',
'--                 || ''- Target Role       : '' || l_role_name || CHR(10)',
'--                 || ''- File Name         : '' || l_filename || CHR(10)',
'--                 || ''- File Format       : Microsoft Excel (.xlsx)'' || CHR(10)',
'--                 || ''- Generation Engine : APEX_DATA_EXPORT (Direct Memory BLOB)'' || CHR(10) || CHR(10)',
'--                 || ''Process Summary:'' || CHR(10)',
'--                 || ''----------------------------------------------------------------------'' || CHR(10)',
'--                 || ''The Excel file was dynamically generated in memory and attached directly'' || CHR(10)',
'--                 || ''to the mail dispatch call without saving to temporary session tables.'' || CHR(10) || CHR(10)',
'--                 || ''Regards,'' || CHR(10)',
'--                 || ''APEX User Management Engine'' || CHR(10)',
'--                 || ''----------------------------------------------------------------------'' || CHR(10)',
'--                 || ''Automated System Notification | Oracle APEX Application Suite'';',
'',
'--     ----------------------------------------------------------------------------',
'--     -- STEP 4: Stage Email Message in Queue',
'--     ----------------------------------------------------------------------------',
'--     -- apex_mail.send enqueues message and returns unique Mail ID',
'--     l_mail_id := apex_mail.send(',
'--         p_to   => l_recipient_email,',
'--         p_from => :APP_EMAIL,',
'--         p_body => l_body_text,',
'--         p_subj => l_subject',
'--     );',
'',
'--     ----------------------------------------------------------------------------',
'--     -- STEP 5: Attach Excel BLOB Content to Enqueued Mail',
'--     ----------------------------------------------------------------------------',
'--     apex_mail.add_attachment(',
'--         p_mail_id    => l_mail_id,',
'--         p_attachment => l_excel_blob,',
'--         p_filename   => l_filename,',
'--         p_mime_type  => l_mime_type',
'--     );',
'',
'--     ----------------------------------------------------------------------------',
'--     -- STEP 6: Force Immediate Delivery from Mail Queue',
'--     ----------------------------------------------------------------------------',
'--     apex_mail.push_queue;',
'',
'-- EXCEPTION',
'--     WHEN OTHERS THEN',
'--         -- Ensure execution context is safely closed in case of runtime errors',
'--         BEGIN',
'--             apex_exec.close(l_context);',
'--         EXCEPTION',
'--             WHEN OTHERS THEN',
'--                 NULL;',
'--         END;',
'        ',
'--         -- Display Error Message in APEX Page UI',
'--         apex_error.add_error(',
'--             p_message          => ''Direct Excel Email Dispatch failed: '' || SQLERRM,',
'--             p_display_location => apex_error.c_inline_in_notification',
'--         );',
'-- END;',
'',
'',
'DECLARE',
'    ----------------------------------------------------------------------------',
'    -- 1. EMAIL CONFIGURATION',
'    ----------------------------------------------------------------------------',
'    l_recipient_email VARCHAR2(255) := ''ARCHI.PATEL@TAVISHINFOTECH.COM'';',
'',
'    l_subject VARCHAR2(255) :=',
'        ''User Report - Excel and PDF Attachments'';',
'',
'',
'    ----------------------------------------------------------------------------',
'    -- 2. COMMON VARIABLES',
'    ----------------------------------------------------------------------------',
'    l_context     APEX_EXEC.t_context;',
'    l_sql_query  VARCHAR2(4000);',
'',
'    l_role_name  VARCHAR2(200);',
'',
'',
'    ----------------------------------------------------------------------------',
'    -- 3. EXCEL VARIABLES',
'    ----------------------------------------------------------------------------',
'    l_excel_export APEX_DATA_EXPORT.t_export;',
'    l_excel_blob   BLOB;',
'    l_excel_name   VARCHAR2(255);',
'',
'    l_excel_mime   VARCHAR2(255) :=',
'        ''application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'';',
'',
'',
'    ----------------------------------------------------------------------------',
'    -- 4. PDF VARIABLES',
'    ----------------------------------------------------------------------------',
'    l_pdf_export APEX_DATA_EXPORT.t_export;',
'    l_pdf_blob   BLOB;',
'    l_pdf_name   VARCHAR2(255);',
'',
'    l_pdf_mime   VARCHAR2(255) :=',
'        ''application/pdf'';',
'',
'',
'   ',
'',
'    ----------------------------------------------------------------------------',
'    -- 6. EMAIL VARIABLES',
'    ----------------------------------------------------------------------------',
'    l_mail_id   NUMBER;',
'    l_body_text CLOB;',
'',
'',
'BEGIN',
'',
'    ----------------------------------------------------------------------------',
'    -- STEP 1: GET ROLE NAME',
'    ----------------------------------------------------------------------------',
'    BEGIN',
'',
'        SELECT role_name',
'          INTO l_role_name',
'          FROM LWF_ROLES',
'         WHERE role_id = :P6_ROLE_ID;',
'',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            l_role_name := ''User_Report'';',
'    END;',
'',
'',
'    ----------------------------------------------------------------------------',
'    -- STEP 2: GENERATE FILE NAMES',
'    ----------------------------------------------------------------------------',
'',
'    l_excel_name :=',
'          ''User_List_''',
'        || REPLACE(l_role_name, '' '', ''_'')',
'        || ''_''',
'        || TO_CHAR(SYSDATE, ''YYYYMMDD_HH24MISS'')',
'        || ''.xlsx'';',
'',
'',
'    l_pdf_name :=',
'          ''User_List_''',
'        || REPLACE(l_role_name, '' '', ''_'')',
'        || ''_''',
'        || TO_CHAR(SYSDATE, ''YYYYMMDD_HH24MISS'')',
'        || ''.pdf'';',
'',
'',
'',
'    ----------------------------------------------------------------------------',
'    -- STEP 3: DEFINE COMMON SQL QUERY',
'    ----------------------------------------------------------------------------',
'',
'    l_sql_query := ''',
'        SELECT',
'            U.FIRST_NAME,',
'            U.LAST_NAME,',
'            U.EMAIL,',
'            U.MOBILE_NUMBER,',
'            R.ROLE_NAME',
'        FROM LWF_USERS U',
'        JOIN LWF_ROLES R',
'          ON U.ROLE_ID = R.ROLE_ID',
'        WHERE R.ROLE_ID = :P6_ROLE_ID'';',
'',
'',
'    ----------------------------------------------------------------------------',
'    -- STEP 4: GENERATE EXCEL',
'    ----------------------------------------------------------------------------',
'',
'    l_context := apex_exec.open_query_context(',
'        p_location  => apex_exec.c_location_local_db,',
'        p_sql_query => l_sql_query',
'    );',
'',
'',
'    l_excel_export := apex_data_export.export(',
'        p_context => l_context,',
'        p_format  => apex_data_export.c_format_xlsx',
'    );',
'',
'',
'    l_excel_blob := l_excel_export.content_blob;',
'',
'',
'    apex_exec.close(l_context);',
'',
'',
'    ----------------------------------------------------------------------------',
'    -- STEP 5: GENERATE PDF',
'    ----------------------------------------------------------------------------',
'',
'    l_context := apex_exec.open_query_context(',
'        p_location  => apex_exec.c_location_local_db,',
'        p_sql_query => l_sql_query',
'    );',
'',
'',
'    l_pdf_export := apex_data_export.export(',
'        p_context => l_context,',
'        p_format  => apex_data_export.c_format_pdf',
'    );',
'',
'',
'    l_pdf_blob := l_pdf_export.content_blob;',
'',
'',
'    apex_exec.close(l_context);',
'',
'',
'    ----------------------------------------------------------------------------',
'    -- STEP 6: WORD / DOCX',
'    ----------------------------------------------------------------------------',
'    --',
'    -- IMPORTANT:',
'    -- APEX_DATA_EXPORT does NOT provide c_format_docx.',
'    --',
'    -- A real DOCX file must be generated using:',
'    --',
'    -- 1. APEX Office Print (AOP), OR',
'    -- 2. Oracle Document Generator, OR',
'    -- 3. Another DOCX generation library/service.',
'    --',
'    -- Therefore l_word_blob must be populated by your DOCX generator.',
'    --',
'    -- Example:',
'    --',
'    -- l_word_blob := <YOUR DOCX GENERATION CODE>;',
'    --',
'    -- After generating the BLOB, the attachment code below will work.',
'    --',
'    ----------------------------------------------------------------------------',
'',
'',
'    ----------------------------------------------------------------------------',
'    -- STEP 7: CREATE EMAIL BODY',
'    ----------------------------------------------------------------------------',
'',
'    l_body_text :=',
'          ''*** USER REPORT ***''',
'        || CHR(10)',
'        || CHR(10)',
'        || ''Hello Administrator,''',
'        || CHR(10)',
'        || CHR(10)',
'        || ''Please find attached the User Details Report.''',
'        || CHR(10)',
'        || CHR(10)',
'        || ''Target Role : ''',
'        || l_role_name',
'        || CHR(10)',
'        || CHR(10)',
'        || ''Attachments:''',
'        || CHR(10)',
'        || ''1. Excel : ''',
'        || l_excel_name',
'        || CHR(10)',
'        || ''2. PDF   : ''',
'        || l_pdf_name',
'        || CHR(10)',
'        || CHR(10)',
'        || ''Regards,''',
'        || CHR(10)',
'        || ''APEX User Management Engine'';',
'',
'',
'    ----------------------------------------------------------------------------',
'    -- STEP 8: CREATE EMAIL',
'    ----------------------------------------------------------------------------',
'',
'    l_mail_id := apex_mail.send(',
'        p_to   => l_recipient_email,',
'        p_from => :APP_EMAIL,',
'        p_body => l_body_text,',
'        p_subj => l_subject',
'    );',
'',
'',
'    ----------------------------------------------------------------------------',
'    -- STEP 9: ATTACH EXCEL',
'    ----------------------------------------------------------------------------',
'',
'    apex_mail.add_attachment(',
'        p_mail_id    => l_mail_id,',
'        p_attachment => l_excel_blob,',
'        p_filename   => l_excel_name,',
'        p_mime_type  => l_excel_mime',
'    );',
'',
'',
'    ----------------------------------------------------------------------------',
'    -- STEP 10: ATTACH PDF',
'    ----------------------------------------------------------------------------',
'',
'    apex_mail.add_attachment(',
'        p_mail_id    => l_mail_id,',
'        p_attachment => l_pdf_blob,',
'        p_filename   => l_pdf_name,',
'        p_mime_type  => l_pdf_mime',
'    );',
'',
'',
'    ----------------------------------------------------------------------------',
'    -- STEP 12: PUSH MAIL QUEUE',
'    ----------------------------------------------------------------------------',
'',
'    apex_mail.push_queue;',
'',
'',
'EXCEPTION',
'',
'    WHEN OTHERS THEN',
'',
'        BEGIN',
'            apex_exec.close(l_context);',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                NULL;',
'        END;',
'',
'',
'        apex_error.add_error(',
'            p_message =>',
'                ''Report Email Dispatch failed: '' || SQLERRM,',
'',
'            p_display_location =>',
'                apex_error.c_inline_in_notification',
'        );',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(36894964512996771948)
,p_process_success_message=>'Email sent successfully with attached Excel file Using PL/SQL !'
,p_internal_uid=>37339633143590973901
,p_created_on=>wwv_flow_imp.dz('20260911055646Z')
,p_updated_on=>wwv_flow_imp.dz('20260911091844Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
